import itertools

def is_all_interval_series(p):
    n = len(p)
    diffs = [abs(p[i+1] - p[i]) for i in range(n-1)]
    return sorted(diffs) == list(range(1, n))

def find_all_interval_series(n):
    for p in itertools.permutations(range(n)):
        if is_all_interval_series(p):
            return p
    return None

print(find_all_interval_series(9))
